DELETE FROM cmd.test_clock;
SELECT set_config('app.test_time','',true);
SELECT set_config('test.reg.body',jsonb_build_object('name','Người đăng ký thử','organization',jsonb_build_object('code','C49ORG','kind','enterprise','display_name','Doanh nghiệp đăng ký command','can_buy',true,'can_sell',false,'tax_code','1919191919','segment_code','processor'),'contact',jsonb_build_object('phone_enc',convert_to('TEST-NOT-ENCRYPTED:0909993999','UTF8'),'phone_hash',digest('0909993999','sha256'),'phone_masked','0909***999','key_id','TEST-NOT-ENCRYPTED'))::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT test.expect_error('C49 app không tự chứng nhận OTP đăng ký','SELECT cmd.record_registration(current_setting(''test.reg.body'')::jsonb,''C49SMS'')','42501')$$);
SELECT test.as_login('db_test_auth',$$SELECT set_config('test.reg.receipt',cmd.record_registration(current_setting('test.reg.body')::jsonb,'C49SMS')::text,true)$$);
SELECT test.as_login('db_test_auth',$$SELECT cmd.record_registration(current_setting('test.reg.body')::jsonb,'C49SMS')$$);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.reg.result',cmd.register_organization(current_setting('test.reg.receipt')::uuid)::text,true)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.register_organization(current_setting('test.reg.receipt')::uuid)$$);
SELECT set_config('test.reg.org',(current_setting('test.reg.result')::jsonb->>'org_id'),true),set_config('test.reg.user',(current_setting('test.reg.result')::jsonb->>'user_id'),true);
SELECT test.check('C49 đăng ký nguyên tử pending, số xác minh, gói free, chưa tự có chủ',EXISTS(SELECT 1 FROM core.organizations WHERE code='C49ORG' AND status='pending' AND NOT is_platform) AND EXISTS(SELECT 1 FROM pii.user_contacts WHERE user_id=current_setting('test.reg.user')::uuid AND phone_verified_at IS NOT NULL) AND (SELECT count(*)=1 FROM core.registration_results WHERE receipt_id=current_setting('test.reg.receipt')::uuid) AND EXISTS(SELECT 1 FROM core.subscriptions WHERE org_id=current_setting('test.reg.org')::uuid AND plan_code='free') AND NOT EXISTS(SELECT 1 FROM core.membership_role_grants r JOIN core.memberships m ON m.id=r.membership_id WHERE m.org_id=current_setting('test.reg.org')::uuid));
SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C49 không đăng ký bằng receipt không tồn tại','SELECT cmd.register_organization(gen_random_uuid())','ck_registration_receipt')$$);
-- Xác minh chủ mới vẫn đúng quy trình hai người và chờ quyền 24h.
