SELECT test.as_login('db_test_verify',$$SELECT set_config('test.reg.verification',cmd.propose_owner_verification(current_setting('test.reg.org')::uuid,current_setting('test.reg.user')::uuid,current_setting('test.reg.evidence')::uuid,'Đối chiếu hồ sơ thật tại adapter thử')::text,true)$$);
SELECT test.as_login('db_test_approve',$$SELECT set_config('test.reg.decision',cmd.approve_owner_verification(current_setting('test.reg.verification')::uuid)::text,true)$$);
