SELECT test.check('C49 đăng ký nối bootstrap giữ thời gian chờ chủ',EXISTS(SELECT 1 FROM core.organizations WHERE code='C49ORG' AND status='active') AND NOT EXISTS(SELECT 1 FROM core.membership_roles r JOIN core.memberships m ON m.id=r.membership_id WHERE m.org_id=current_setting('test.reg.org')::uuid AND r.role_code='owner'));
