SELECT test.as_login('db_test_verify',$$SELECT test.expect_error('C49 người xác minh không tự duyệt','SELECT cmd.approve_decision(current_setting(''test.reg.extra'')::uuid)','ck_decision_two_people')$$);
SELECT test.as_login('db_test_approve',$$SELECT set_config('test.reg.extraDecision',cmd.approve_decision(current_setting('test.reg.extra')::uuid)::text,true)$$);
