SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C49 gói trả phí phải có chứng từ billing','SELECT cmd.change_subscription(current_setting(''test.reg.org'')::uuid,''procurement'',''C49PLAN'')','ck_subscription_proof')$$);
SELECT set_config('test.reg.bill',(test.command_doc('C49BILL')||jsonb_build_object('canonical_content',jsonb_build_object('billing_org_id',current_setting('test.reg.org'),'plan_code','procurement','amount_vnd',1500000,'result','paid','provider_reference','C49-BILLING-RECEIPT')))::text,true);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.reg.proof',cmd.record_subscription_payment(current_setting('test.reg.org')::uuid,'procurement',current_setting('test.reg.bill')::jsonb)::text,true)$$);
