SELECT test.as_login('db_test_system',$$SELECT set_config('test.reg.plan',cmd.change_subscription(current_setting('test.reg.org')::uuid,'procurement','C49PLAN',current_setting('test.reg.proof')::uuid)::text,true)$$);
