SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C49 khóa đổi gói khác nội dung bị chặn','SELECT cmd.change_subscription(current_setting(''test.reg.org'')::uuid,''free'',''C49PLAN'')','IDEMPOTENCY_CONFLICT')$$);
SELECT test.check('C49 đổi gói lưu lịch sử không chồng lấn, retry một lần',EXISTS(SELECT 1 FROM core.subscriptions WHERE org_id=current_setting('test.reg.org')::uuid AND plan_code='free' AND upper(active_during)=ref.clock_at()) AND EXISTS(SELECT 1 FROM core.subscriptions WHERE id=current_setting('test.reg.plan')::uuid AND plan_code='procurement' AND active_during@>ref.clock_at()) AND (SELECT count(*)=1 FROM core.subscription_changes WHERE request_key='C49PLAN'));
DELETE FROM cmd.test_clock;
