SELECT test.as_login('db_test_buyer',$$SELECT test.expect_error('C49 app không đăng bảng quyết toán hệ thống','SELECT cmd.attach_system_document(''settlement'',current_setting(''test.sys.basis'')::uuid,current_setting(''test.sys.doc'')::jsonb)','42501')$$);
