-- Cache AI nhận mã lý do đã whitelist, không nhận giá kín/nội dung tùy ý.
SELECT set_config('test.cache.line',(SELECT l.id::text FROM core.demand_lines l JOIN core.demands d ON d.id=l.demand_id WHERE d.code='CMD-DEMAND' LIMIT 1),true);
SELECT set_config('test.cache.rows',jsonb_build_array(jsonb_build_object('lot_id',(SELECT id FROM core.lots WHERE code='C48HELPER-LOT'),'match_group','partial','score_bps',9000,'distance_m',1500,'promiseable_qty',1000000,'reasons',jsonb_build_array('product','grade','partial_quantity')))::text,true),set_config('test.cache.expires',(now()+interval '30 minutes')::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT test.expect_error('C49 app không ghi cache AI','SELECT cmd.cache_match_candidates(current_setting(''test.cache.line'')::uuid,''C49CACHE'',''TEST-V1'',current_setting(''test.cache.rows'')::jsonb,decode(repeat(''ab'',32),''hex''),current_setting(''test.cache.expires'')::timestamptz)','42501')$$);
SELECT test.as_login('db_test_system',$$SELECT test.expect_error('C49 cache sai hash bị chặn','SELECT cmd.cache_match_candidates(current_setting(''test.cache.line'')::uuid,''C49CACHE'',''TEST-V1'',current_setting(''test.cache.rows'')::jsonb,decode(repeat(''ab'',32),''hex''),current_setting(''test.cache.expires'')::timestamptz)','ck_match_cache')$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.cache_match_candidates(current_setting('test.cache.line')::uuid,'C49CACHE','TEST-V1',current_setting('test.cache.rows')::jsonb,digest((current_setting('test.cache.rows')::jsonb)::text,'sha256'),current_setting('test.cache.expires')::timestamptz)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.cache_match_candidates(current_setting('test.cache.line')::uuid,'C49CACHE','TEST-V1',current_setting('test.cache.rows')::jsonb,digest((current_setting('test.cache.rows')::jsonb)::text,'sha256'),current_setting('test.cache.expires')::timestamptz)$$);
SELECT test.check('C49 cache có hash/expiry, chỉ lý do chuẩn và một batch',EXISTS(SELECT 1 FROM mkt.match_candidates WHERE demand_line_id=current_setting('test.cache.line')::uuid AND lot_id=(SELECT id FROM core.lots WHERE code='C48HELPER-LOT') AND hard_filters_passed AND algorithm_version='TEST-V1') AND (SELECT count(*)=1 FROM mkt.command_cache_batches WHERE request_key='C49CACHE'));
SET CONSTRAINTS ALL IMMEDIATE;
-- Các entry point không mở đường DML hoặc helper tự ghép trạng thái/tiền/lượng.
SELECT test.check('C49 helper mới không cấp EXECUTE cho runtime',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='cmd' AND p.proname IN ('require_lot_editor','payment_reconciliation_task','submit_acceptance_internal','finalize_acceptance_quantity') AND (has_function_privilege('agiviet_app',p.oid,'EXECUTE') OR has_function_privilege('agiviet_orchestrator',p.oid,'EXECUTE'))));
SELECT test.check('C49 cả auth/app/system entry point đều SECURITY DEFINER và search_path cố định',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='cmd' AND (has_function_privilege('agiviet_app',p.oid,'EXECUTE') OR has_function_privilege('agiviet_orchestrator',p.oid,'EXECUTE') OR has_function_privilege('agiviet_auth_worker',p.oid,'EXECUTE')) AND (NOT p.prosecdef OR NOT EXISTS(SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%'))));
